<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>AIVA / Grace - Explainer</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  body {
    font-family: 'Segoe UI', system-ui, sans-serif;
    background: #f8f9fa;
    color: #333;
    line-height: 1.6;
    padding: 20px;
    max-width: 960px;
    margin: 0 auto;
    min-height: 100vh;
  }

  header {
    text-align: center;
    margin-bottom: 30px;
  }

  header h1 {
    font-size: 2.2rem;
    margin-bottom: 10px;
    color: #1a73e8;
  }

  header p {
    font-size: 1rem;
    color: #666;
    margin-bottom: 20px;
  }

  /* Step visualization container */
  .visualization {
    margin-bottom: 40px;
    padding: 20px;
    background: #fff;
    border-radius: 12px;
    box-shadow: 0 4px 6px rgba(0,0,0,0.08);
  }

  /* Step label */
  #step-label {
    text-align: center;
    font-size: 1.4rem;
    font-weight: 600;
    margin-bottom: 20px;
    color: #1a73e8;
  }

  /* Buttons */
  .buttons {
    display: flex;
    gap: 12px;
    justify-content: center;
    flex-wrap: wrap;
  }

  button {
    padding: 10px 20px;
    font-size: 1rem;
    border: 2px solid #1a73e8;
    background: #fff;
    color: #1a73e8;
    border-radius: 8px;
    cursor: pointer;
    transition: background 0.2s, border-color 0.2s;
  }

  button:hover {
    background: #e6f2ff;
    border-color: #1a73e8;
  }

  button:focus-visible {
    outline: 3px solid #1a73e8;
    outline-offset: 2px;
  }

  /* Reduced motion support */
  @media (prefers-reduced-motion: reduce) {
    .visualization *,
    button,
    #step-label {
      transition-duration: 0.01ms !important;
      animation-duration: 0.01ms !important;
    }
  }

  /* Optional capabilities area */
  .optional {
    margin-top: 30px;
    padding: 20px;
    background: #f1f3f5;
    border-radius: 12px;
    border: 1px solid #d0d7de;
  }

  .optional h3 {
    margin-bottom: 10px;
    color: #555;
  }

  .optional ul {
    list-style: none;
    padding-left: 0;
  }

  .optional li {
    padding: 8px 0;
    border-bottom: 1px solid #e5e7eb;
  }

  .optional li:last-child {
    border-bottom: none;
  }

  .optional a {
    color: #1a73e8;
    text-decoration: none;
  }

  .sample-request {
    background: #fff;
    padding: 20px;
    border-radius: 12px;
    margin-top: 20px;
    border: 1px solid #d0d7de;
  }

  .sample-request h3 {
    margin-bottom: 10px;
    color: #1a73e8;
  }

  .sample-request p {
    font-size: 1.1rem;
    color: #333;
  }

  /* Canvas for cartoon drawing */
  canvas#charCanvas {
    max-width: 100%;
    border: 2px solid #333;
    border-radius: 8px;
    background: #fff;
  }
</style>
</head>
<body>

<header>
  <h1>AIVA / Grace - Explainer</h1>
  <p>AIVA is the PC-side companion runtime; Grace is its conversational persona. This demo simulates the current architecture without live telemetry.</p>
</header>

<div class="visualization">
  <div id="step-label">Step 0: Introduction</div>

  <div class="buttons">
    <button id="next">Next</button>
    <button id="reset">Reset</button>
    <button id="play">Play</button>
  </div>

  <canvas id="charCanvas"></canvas>
</div>

<div class="optional">
  <h3>Optional Capabilities (outside the main chat path)</h3>
  <ul>
    <li><a href="#">Canvas</a> - Drawing utilities for custom illustrations.</li>
    <li><a href="#">Imaging</a> - Image processing for the sidecar.</li>
    <li><a href="#">MOSS</a> - Optional raster painting sidecar.</li>
  </ul>
</div>

<div class="sample-request">
  <h3>Sample Request</h3>
  <p>"How does AIVA remember our conversation?"</p>
</div>

<script>
// AIVA_DEMO object with required methods
window.AIVA_DEMO = {
  reset: function() {
    this.step = 0;
    this.playing = false;
    // Cancel any scheduled playback
    clearTimeout(this.timer);
    // Update UI
    document.getElementById('step-label').textContent = 'Step 0: Introduction';
    // Reset canvas animation
    const canvas = document.getElementById('charCanvas');
    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    // Add a reset message
    ctx.fillStyle = '#1a73e8';
    ctx.font = '20px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Reset to step 0', canvas.width/2, canvas.height/2);
  },

  next: function() {
    if (this.step >= 6) return;
    this.step++;
    this.playing = true;
    this.updateUI();
  },

  togglePlay: function() {
    this.playing = !this.playing;
    this.updateUI();
  },

  getState: function() {
    return { step: this.step, playing: this.playing };
  },

  updateUI: function() {
    const label = document.getElementById('step-label');
    const steps = [
      'Step 0: Introduction',
      'Step 1: Encoding',
      'Step 2: Decoding',
      'Step 3: Assembly',
      'Step 4: Routing',
      'Step 5: Response',
      'Step 6: Memory'
    ];
    label.textContent = steps[this.step];
  }
};

// Step 0: Initial state
window.AIVA_DEMO.step = 0;
window.AIVA_DEMO.playing = false;

// Initialize buttons
document.getElementById('next').addEventListener('click', function() {
  window.AIVA_DEMO.next();
});

document.getElementById('reset').addEventListener('click', function() {
  window.AIVA_DEMO.reset();
});

document.getElementById('play').addEventListener('click', function() {
  window.AIVA_DEMO.togglePlay();
});

// Canvas animation for cartoon characters
const canvas = document.getElementById('charCanvas');
const ctx = canvas.getContext('2d');
let animationFrameId;
let characters = [];
let currentStep = 0;

function initCanvas() {
  canvas.width = window.innerWidth * 2;
  canvas.height = window.innerHeight * 2;
  drawCharacters();
}

function drawCharacters() {
  const w = canvas.width;
  const h = canvas.height;
  ctx.clearRect(0, 0, w, h);

  // Background
  ctx.fillStyle = '#f0f2f5';
  ctx.fillRect(0, 0, w, h);

  // Title
  ctx.fillStyle = '#1a73e8';
  ctx.font = 'bold 28px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('AIVA / Grace', w / 2, 50);

  // Steps
  const steps = [
    { title: 'Step 0: Introduction', y: 120, x: 100, width: 150, height: 40, color: '#1a73e8', active: false },
    { title: 'Step 1: Encoding', y: 200, x: 100, width: 150, height: 40, color: '#1a73e8', active: false },
    { title: 'Step 2: Decoding', y: 280, x: 100, width: 150, height: 40, color: '#1a73e8', active: false },
    { title: 'Step 3: Assembly', y: 360, x: 100, width: 150, height: 40, color: '#1a73e8', active: false },
    { title: 'Step 4: Routing', y: 440, x: 100, width: 150, height: 40, color: '#1a73e8', active: false },
    { title: 'Step 5: Response', y: 520, x: 100, width: 150, height: 40, color: '#1a73e8', active: false },
    { title: 'Step 6: Memory', y: 600, x: 100, width: 150, height: 40, color: '#1a73e8', active: true }
  ];

  steps.forEach((step, i) => {
    const isActive = i === currentStep;
    step.active = isActive;
    step.color = isActive ? '#16a34a' : '#1a73e8';

    ctx.fillStyle = step.color;
    ctx.fillRect(step.x, step.y, step.width, step.height);

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 24px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText(step.title, step.x + step.width / 2, step.y + step.height / 2);
  });

  // Arrow indicators
  for (let i = 0; i < steps.length - 1; i++) {
    const prev = steps[i];
    const next = steps[i + 1];
    ctx.strokeStyle = '#888';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(prev.x + prev.width, (prev.y + prev.height) / 2);
    ctx.lineTo(next.x, (next.y + next.height) / 2);
    ctx.stroke();
  }

  // Update step label
  const stepLabel = document.getElementById('step-label');
  const stepsLabels = [
    'Step 0: Introduction',
    'Step 1: Encoding',
    'Step 2: Decoding',
    'Step 3: Assembly',
    'Step 4: Routing',
    'Step 5: Response',
    'Step 6: Memory'
  ];
  stepLabel.textContent = stepsLabels[currentStep];
}

function animate() {
  requestAnimationFrame(animate);
  // Move step forward one step
  currentStep = (currentStep + 1) % 7;
  // Update canvas
  drawCharacters();
}

function startAnimation() {
  if (animationFrameId) return;
  animationFrameId = requestAnimationFrame(animate);
}

function resizeCanvas() {
  initCanvas();
}

window.addEventListener('resize', resizeCanvas);

// Start animation when DOM is ready
document.addEventListener('DOMContentLoaded', function() {
  resizeCanvas();
  startAnimation();
});
</script>

</body>
</html>
